import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Keynote- Building and Sustaining Momentum in Open-Source Storage - Brett Kelly, 45Drives","description":"","frontmatter":{"title":"Keynote- Building and Sustaining Momentum in Open-Source Storage - Brett Kelly, 45Drives","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","Open Source Storage","Distributed Storage","Storage Performance","Ceph Community"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Keynote_-_Building_and_Sustaining_Momentum_in_Open-Source_Storage_-_Brett_Kelly_45Drives.md","filePath":"posts/2025/Keynote_-_Building_and_Sustaining_Momentum_in_Open-Source_Storage_-_Brett_Kelly_45Drives.md","lastUpdated":1780459816000}'),i={name:"posts/2025/Keynote_-_Building_and_Sustaining_Momentum_in_Open-Source_Storage_-_Brett_Kelly_45Drives.md"};function s(a,e,l,g,u,_){return r(),n("div",null,[...e[0]||(e[0]=[o('<h3 id="ceph-会议纪要-45-drives-主题演讲《sustaining-momentum-in-open-source-storage》" tabindex="-1">Ceph 会议纪要：45 Drives 主题演讲《Sustaining Momentum in Open Source Storage》 <a class="header-anchor" href="#ceph-会议纪要-45-drives-主题演讲《sustaining-momentum-in-open-source-storage》" aria-label="Permalink to &quot;Ceph 会议纪要：45 Drives 主题演讲《Sustaining Momentum in Open Source Storage》&quot;">​</a></h3><h4 id="_1-会议概览" tabindex="-1"><strong>1. 会议概览</strong> <a class="header-anchor" href="#_1-会议概览" aria-label="Permalink to &quot;**1. 会议概览**&quot;">​</a></h4><ul><li><strong>会议名称</strong>: Ceph Conference (CephCon)</li><li><strong>地点</strong>: 加拿大温哥华</li><li><strong>演讲嘉宾</strong>: Brett Kelly（45 Drives 技术总监）</li><li><strong>核心主题</strong>: <ul><li>45 Drives 对 Ceph 生态的贡献与角色</li><li>Ceph 在实际部署中的挑战与用户反馈</li><li>未来技术方向与社区协作建议</li></ul></li></ul><h4 id="_2-关键讨论内容" tabindex="-1"><strong>2. 关键讨论内容</strong> <a class="header-anchor" href="#_2-关键讨论内容" aria-label="Permalink to &quot;**2. 关键讨论内容**&quot;">​</a></h4><p><strong>(1) 45 Drives 公司介绍</strong></p><ul><li><strong>业务定位</strong>: 硬件制造商和 Ceph 解决方案供应商，提供定制化存储服务器和高密度 JBOD/SAN 设备。</li><li><strong>Ceph 参与</strong>: 深度参与 Ceph 项目 8-9 年，支持 Rocky Linux 等开源生态，通过赞助、社区教育、用户支持等方式推动 Ceph 普及。</li></ul><p><strong>(2) Ceph 的市场定位与成功经验</strong></p><ul><li><strong>“Ceph for Everyone” 策略</strong>: 强调 Ceph 不仅适用于大规模集群，也适用于中小规模场景，通过硬件与软件协同设计降低用户门槛。</li><li><strong>用户痛点反馈</strong>: 性能瓶颈、高密度存储挑战、开源采纳风险。</li></ul><p><strong>(3) 竞争与未来方向</strong></p><ul><li><strong>技术优先级</strong>: 提升 IOPS/美元性价比，优化 NVMe 性能，推动硬件厂商与 Ceph 社区合作。</li><li><strong>社区协作</strong>: 提倡“开源共赢”，鼓励更多厂商加入 Ceph 基金会。</li></ul><h4 id="_3-行动计划" tabindex="-1"><strong>3. 行动计划</strong> <a class="header-anchor" href="#_3-行动计划" aria-label="Permalink to &quot;**3. 行动计划**&quot;">​</a></h4><ul><li><strong>短期</strong>: 展示定制化 Ceph 硬件，与厂商合作验证新一代硬盘/NVMe 在 Ceph 集群中的表现。</li><li><strong>长期</strong>: 推动 Crimson OSD 落地，优化高性能场景下的资源利用率，参与 Ceph 文档改进项目。</li></ul><h4 id="_4-保留的关键术语-中英对照" tabindex="-1"><strong>4. 保留的关键术语（中英对照）</strong> <a class="header-anchor" href="#_4-保留的关键术语-中英对照" aria-label="Permalink to &quot;**4. 保留的关键术语（中英对照）**&quot;">​</a></h4><ul><li><strong>架构组件</strong>: OSD/MON/MDS, PG, RADOS, CRUSH algorithm</li><li><strong>存储类型</strong>: Object/Block/File System Storage (RBD/RGW/CephFS)</li><li><strong>技术概念</strong>: Erasure Coding, Thin Provisioning, Tiering, Failure Domain</li><li><strong>生态工具</strong>: librados, cephadm, Dashboard</li></ul><h4 id="_5-总结" tabindex="-1"><strong>5. 总结</strong> <a class="header-anchor" href="#_5-总结" aria-label="Permalink to &quot;**5. 总结**&quot;">​</a></h4><p>45 Drives 从硬件厂商视角提出：Ceph 需平衡<strong>高性能</strong>、<strong>易用性</strong>和<strong>高密度存储支持</strong>，同时加强社区与硬件厂商的协作。此次演讲为后续版本演进提供了明确的用户需求输入。</p><p>（注：具体技术讨论可参考 Brett Kelly 提到的 [45 Drives YouTube 频道](https: <a href="//www.youtube.com/45drives" target="_blank" rel="noreferrer">//www.youtube.com/45drives</a>) 及 Ceph 基金会文档。）</p>',17)])])}const d=t(i,[["render",s]]);export{h as __pageData,d as default};
